import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="Nhịp Phố", page_icon="🎵", layout="centered")

# Ẩn bớt phần thừa của Streamlit cho game rộng rãi hơn
st.markdown(
    """
    <style>
    #MainMenu, footer, header {visibility: hidden;}
    .block-container {padding-top: 1rem; padding-bottom: 0;}
    </style>
    """,
    unsafe_allow_html=True,
)

GAME_HTML = r"""<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nhịp Phố</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(at top,#353965,#111321 70%);color:#f8f8ff;font:16px system-ui;padding:20px}.game{width:min(780px,100%)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.brand{font-size:30px;font-weight:900}.brand span{color:#63f5e7}.tag,.help{color:#a7abc3;font-size:13px}.pill{display:inline-block;background:#20233a;padding:9px 13px;border-radius:12px;margin-left:6px;color:#bfc2d7}.pill b{color:white;margin-left:6px}.stage{height:460px;position:relative;overflow:hidden;border:1px solid #45496d;border-radius:20px;background:radial-gradient(circle at 15% 18%,#fff8 1px,transparent 2px),radial-gradient(circle at 79% 24%,#fff8 1px,transparent 2px),linear-gradient(#202444,#4d315d);box-shadow:0 20px 60px #050611}.stage:after{content:'';position:absolute;inset:auto 0 0;height:100px;background:linear-gradient(0deg,#17182a,#292344);clip-path:polygon(0 100%,0 48%,12% 48%,12% 20%,22% 20%,22% 68%,34% 68%,34% 35%,48% 35%,48% 60%,60% 60%,60% 25%,73% 25%,73% 55%,88% 55%,88% 33%,100% 33%,100% 100%)}.label{position:absolute;top:17px;width:100%;text-align:center;letter-spacing:.2em;color:#c6c8db;font-size:12px}.lanes{position:absolute;z-index:1;top:62px;bottom:0;left:50%;transform:translateX(-50%);width:min(420px,90%);display:grid;grid-template-columns:repeat(4,1fr);background:#11132266}.lane{position:relative;border-right:1px solid #ffffff18}.receptor{position:absolute;top:67%;left:50%;transform:translate(-50%,-50%);height:52px;width:52px;border:2px solid #ffffff77;border-radius:14px;display:grid;place-items:center;font-size:24px}.note{position:absolute;left:50%;transform:translate(-50%,-50%);width:46px;height:46px;border-radius:14px;display:grid;place-items:center;font-size:23px;font-weight:bold;box-shadow:0 5px 18px #0006}.n0{background:#63f5e7;color:#111}.n1{background:#ff6f91;color:#211}.n2{background:#ffe66d;color:#211}.n3{background:#a88bff;color:#211}.feedback{position:absolute;z-index:2;top:46%;left:50%;transform:translate(-50%,-50%);font-size:24px;font-weight:900}.bottom{position:absolute;z-index:2;bottom:14px;left:18px;right:18px;display:flex;justify-content:space-between;font-size:12px;color:#e0e0ed}.health{height:7px;width:140px;background:#fff3;border-radius:9px;margin-top:5px;overflow:hidden}.health i{display:block;height:100%;background:#63f5e7;width:100%}.overlay{position:absolute;z-index:4;inset:0;background:#111322dd;display:grid;place-items:center;text-align:center;padding:20px}.card{max-width:420px}.card h1{font-size:38px;margin:0 0 8px}.card p{line-height:1.55;color:#d0d1e0}.btn{background:#63f5e7;color:#101222;border:0;padding:13px 24px;border-radius:12px;font-size:16px;font-weight:900;cursor:pointer}.controls{display:flex;justify-content:center;gap:9px;margin:14px}.key{height:48px;width:58px;border:1px solid#fff4;border-radius:12px;background:#20233a;color:white;font-size:22px;cursor:pointer;touch-action:manipulation}.help{text-align:center}.on{border-color:#63f5e7!important;color:#63f5e7}.hit{background:#63f5e7;color:#111}@media(max-width:500px){.stage{height:420px}.brand{font-size:25px}}</style><body><main class="game"><header><div><div class="brand">NHỊP <span>PHỐ</span></div><div class="tag">Game nhịp điệu mini trên trình duyệt</div></div><div><div class="pill">ĐIỂM <b id="score">0</b></div><div class="pill">COMBO <b id="combo">0</b></div></div></header><section class="stage"><div class="label">ĐÊM NAY, SÂN KHẤU LÀ CỦA BẠN</div><div id="lanes" class="lanes"></div><div id="feedback" class="feedback"></div><div class="bottom"><div>CHÍNH XÁC <span id="acc">—</span><div class="health"><i id="health"></i></div></div><div>ĐÊM LẤP LÁNH · 110 BPM</div></div><div id="overlay" class="overlay"><div class="card"><h1>Đêm <span style="color:#63f5e7">Lấp Lánh</span></h1><p>Bấm phím ← ↓ ↑ → khi nốt nhạc chạm ô sáng. Canh đúng nhịp để ghi điểm!</p><button class="btn" id="start">CHƠI NGAY</button><p class="help">Có thể chạm các nút bên dưới nếu chơi trên điện thoại.</p></div></div></section><div class="controls"><button class="key" data-lane="0">←</button><button class="key" data-lane="1">↓</button><button class="key" data-lane="2">↑</button><button class="key" data-lane="3">→</button></div><div class="help">Mẹo: bật âm lượng để nghe nhịp 🎵</div></main><script>const arrows=['←','↓','↑','→'],lanes=document.querySelector('#lanes');arrows.forEach((a,i)=>lanes.insertAdjacentHTML('beforeend','<div class="lane"><div class="receptor" id="r'+i+'">'+a+'</div></div>'));let notes=[],playing=false,score=0,combo=0,health=100,hits=0,total=0,audio,timer,raf;const beat=60000/110,travel=1400,chart=[0,1,2,3,0,2,1,3,1,0,3,2,0,1,2,3,2,0,1,3,0,2,3,1,1,2,0,3,2,1,3,0,0,2,1,3,2,1,0,3];function tone(f,d=.1){if(!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}function update(){document.querySelector('#score').textContent=score;document.querySelector('#combo').textContent=combo;document.querySelector('#health').style.width=health+'%';document.querySelector('#acc').textContent=total?Math.round(hits/total*100)+'%':'—'}function start(){audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();notes=[];score=combo=hits=total=0;health=100;playing=true;document.querySelector('#overlay').style.display='none';const now=performance.now()+1800;chart.forEach((lane,i)=>notes.push({lane,time:now+900+i*beat*.72,done:false,el:null}));timer=setInterval(()=>tone(130,.11),beat);update();loop()}function flash(s){let f=document.querySelector('#feedback');f.textContent=s;f.style.color=s==='Trượt!'?'#ff6f91':'#ffe66d';setTimeout(()=>{if(f.textContent===s)f.textContent=''},400)}function hit(i){if(!playing)return;let n=notes.filter(x=>!x.done&&x.lane===i).sort((a,b)=>Math.abs(a.time-performance.now())-Math.abs(b.time-performance.now()))[0];document.querySelector('#r'+i).classList.add('hit');setTimeout(()=>document.querySelector('#r'+i).classList.remove('hit'),100);if(!n||Math.abs(n.time-performance.now())>180)return;n.done=true;hits++;total++;combo++;let d=Math.abs(n.time-performance.now());score+=d<65?300:d<125?180:100;health=Math.min(100,health+2);flash(d<65?'Tuyệt!':'Hay lắm!');tone([440,523,659,784][i],.12);update()}function loop(){if(!playing)return;let now=performance.now();for(let n of notes){if(n.done)continue;if(!n.el&&now>n.time-travel){n.el=document.createElement('div');n.el.className='note n'+n.lane;n.el.textContent=arrows[n.lane];lanes.children[n.lane].appendChild(n.el)}if(n.el)n.el.style.top='calc(67% + '+((now-n.time)/travel*100)+'%)';if(now>n.time+180){n.done=true;total++;combo=0;health=Math.max(0,health-12);flash('Trượt!');update()}}if(notes.every(n=>n.done)){finish();return}raf=requestAnimationFrame(loop)}function finish(){playing=false;clearInterval(timer);cancelAnimationFrame(raf);document.querySelector('#overlay').style.display='grid';document.querySelector('#overlay .card').innerHTML='<h1>'+ (health?'Hay lắm!':'Hết lượt!')+'</h1><p>Bạn đạt <b>'+score+'</b> điểm · độ chính xác <b>'+(total?Math.round(hits/total*100):0)+'%</b>.</p><button class="btn"id="start">CHƠI LẠI</button>';document.querySelector('#start').onclick=start}document.querySelector('#start').onclick=start;document.addEventListener('keydown',e=>{let i=['ArrowLeft','ArrowDown','ArrowUp','ArrowRight'].indexOf(e.key);if(i>=0){e.preventDefault();hit(i)}});document.querySelectorAll('.key').forEach(b=>b.onclick=()=>hit(+b.dataset.lane));</script></body></html>"""

# Game chạy trong iframe: bấm "CHƠI NGAY" để iframe nhận phím mũi tên
components.html(GAME_HTML, height=800, scrolling=False)
